// Example of JVM flags to tune Young Generation behavior
// -Xmn sets the total Young Gen size
// -XX:SurvivorRatio=8 means Eden is 8x larger than one Survivor space
// -XX:MaxTenuringThreshold=6 limits age before promotion

java -Xms2g -Xmx2g -Xmn512m -XX:SurvivorRatio=8 -XX:MaxTenuringThreshold=6 -jar application.jar
